INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'violent', 'adj.', '/ˈvaɪələnt/', '狂暴的;凶暴的;暴力的', 'The fighting on the beach was sudden and violent.', '海滩上的战斗来得突然而猛烈。', 'The D-Day Landings', 1, 0, 'senior', 'wordlist', 'elective3', 'U3', 'violent fighting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'violence', 'n.', '/ˈvaɪələns/', '暴力;暴行;猛烈', 'Few soldiers were ready for the violence they met at Omaha Beach.', '很少有士兵对他们在奥马哈海滩遭遇的暴力有所准备。', 'The D-Day Landings', 2, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the violence of war', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'landing', 'n.', '/ˈlændɪŋ/', '(军队的)登陆;着陆', 'The D-Day landings began at dawn on 6 June 1944.', '诺曼底登陆于1944年6月6日黎明开始。', 'The D-Day Landings', 3, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the D-Day landings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'allied', 'adj.', '/ˈælaɪd/', '(第二次世界大战)同盟国的;联合的', 'The Allied troops were made up of British, Canadian and American soldiers.', '同盟国部队由英国、加拿大和美国士兵组成。', 'The D-Day Landings', 4, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the Allied forces', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'troop', 'n.', '/truːp/', '部队;军队(常用复数)', 'Thousands of troops crossed the English Channel that night.', '那天夜里,数千名士兵渡过了英吉利海峡。', 'The D-Day Landings', 5, 0, 'senior', 'wordlist', 'elective3', 'U3', 'send in troops', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tide', 'n.', '/taɪd/', '潮水;潮汐;趋势', 'The commanders waited for the right moon and tide before the attack.', '指挥官们等到合适的月相和潮水后才发起进攻。', 'The D-Day Landings', 6, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the tide has turned', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'supreme', 'adj.', '/sʊˈpriːm/', '最高的;至高无上的', 'General Eisenhower was the Supreme Commander of the Allied forces.', '艾森豪威尔将军是同盟国部队的最高指挥官。', 'The D-Day Landings', 7, 0, 'senior', 'wordlist', 'elective3', 'U3', 'Supreme Commander', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'commander', 'n.', '/kəˈmɑːndə/', '指挥官;司令;长官', 'The commander gave the order to begin Operation Overlord.', '指挥官下令开始“霸王行动”。', 'The D-Day Landings', 8, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a wise commander', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'parachute', 'n.', '/ˈpærəʃuːt/', '降落伞', 'Thousands of soldiers landed by parachute behind enemy lines.', '数千名士兵乘降落伞降落在敌后。', 'The D-Day Landings', 9, 0, 'senior', 'wordlist', 'elective3', 'U3', 'land by parachute', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'objective', 'n.', '/əbˈdʒektɪv/', '目的;目标', 'Their objective was to reach the Normandy beaches before noon.', '他们的目标是在中午前到达诺曼底海滩。', 'The D-Day Landings', 10, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a clear objective', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'coastline', 'n.', '/ˈkəʊstlaɪn/', '海岸线', 'The attack covered about 80 kilometres of French coastline.', '进攻沿着约80公里的法国海岸线展开。', 'The D-Day Landings', 11, 0, 'senior', 'wordlist', 'elective3', 'U3', 'along the coastline', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'horror', 'n.', '/ˈhɒrə/', '惊恐;恐怖;可怕的事', 'On the beach the men saw the full horror of war.', '在海滩上,这些人见识到了战争全部的恐怖。', 'The D-Day Landings', 12, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the horror of war', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'drown', 'v.', '/draʊn/', '(使)淹死;溺死', 'Some boats were hit and many men drowned before reaching land.', '一些船只被击中,许多人还没上岸就淹死了。', 'The D-Day Landings', 13, 0, 'senior', 'wordlist', 'elective3', 'U3', 'drown at sea', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gunfire', 'n.', '/ˈɡʌnfaɪə/', '炮火;枪炮射击', 'Those who made it to the beach faced heavy machine gunfire.', '上了海滩的人面对着猛烈的机枪火力。', 'The D-Day Landings', 14, 0, 'senior', 'wordlist', 'elective3', 'U3', 'heavy gunfire', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tank', 'n.', '/tæŋk/', '坦克;箱;罐', 'By mid-morning, bodies lay among the tanks on the sand.', '到上午中段,尸体散落在沙滩的坦克之间。', 'The D-Day Landings', 15, 0, 'senior', 'wordlist', 'elective3', 'U3', 'among the tanks', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recall', 'v.', '/rɪˈkɔːl/', '回想;回忆起;召回', 'One soldier recalled how he barely made it across the beach.', '一名士兵回忆起他是如何勉强冲过海滩的。', 'The D-Day Landings', 16, 0, 'senior', 'wordlist', 'elective3', 'U3', 'recall the day', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barely', 'adv.', '/ˈbeəli/', '勉强才能;几乎不', 'With bombs falling all around, he barely made it to safety.', '炸弹在四周落下,他勉强才到达安全地带。', 'The D-Day Landings', 17, 0, 'senior', 'wordlist', 'elective3', 'U3', 'barely made it', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'liberate', 'v.', '/ˈlɪbəreɪt/', '解放(城市、国家等);使获自由', 'By late August, the Allies had liberated Paris.', '到8月底,同盟国已解放了巴黎。', 'The D-Day Landings', 18, 0, 'senior', 'wordlist', 'elective3', 'U3', 'liberate a city', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'memorial', 'adj.', '/məˈmɔːriəl/', '纪念的;追悼的', 'People came together for memorial ceremonies on both sides of the Channel.', '人们在海峡两岸聚集举行纪念仪式。', 'The D-Day Landings', 19, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a memorial ceremony', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'solemn', 'adj.', '/ˈsɒləm/', '严肃的;庄重的', 'The ceremony was a solemn and moving occasion for everyone there.', '对在场的每个人来说,这场仪式都庄严而动人。', 'The D-Day Landings', 20, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a solemn occasion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'condemn', 'v.', '/kənˈdem/', '谴责;使陷于不幸境地', 'World leaders today condemn the cruelty of every war.', '今天的世界领导人谴责一切战争的残酷。', 'The D-Day Landings', 21, 0, 'senior', 'wordlist', 'elective3', 'U3', 'condemn violence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'outstanding', 'adj.', '/aʊtˈstændɪŋ/', '杰出的;优秀的;未付的', 'Their outstanding acts of courage will always be remembered.', '他们杰出的勇敢行为将永远被铭记。', 'The D-Day Landings', 22, 0, 'senior', 'wordlist', 'elective3', 'U3', 'outstanding courage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'uniform', 'n.', '/ˈjuːnɪfɔːm/', '制服;军装', 'The soldiers'' uniforms were torn and covered in mud.', '士兵们的制服破烂不堪,沾满了泥。', 'The D-Day Landings', 23, 0, 'senior', 'wordlist', 'elective3', 'U3', 'wear a uniform', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bomb', 'v.', '/bɒm/', '轰炸;n. 炸弹', 'The enemy bombed the city more than two hundred times.', '敌人对这座城市轰炸了两百多次。', 'The D-Day Landings', 24, 0, 'senior', 'wordlist', 'elective3', 'U3', 'bomb a city', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'peacekeeping', 'n.', '/ˈpiːsˌkiːpɪŋ/', '维持和平(的行动)', 'China plays an important role in UN peacekeeping today.', '如今中国在联合国维和行动中发挥着重要作用。', 'The D-Day Landings', 25, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a peacekeeping mission', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'peacekeeper', 'n.', '/ˈpiːsˌkiːpə/', '维和人员', 'The peacekeepers helped warring parties keep to their agreements.', '维和人员帮助交战各方遵守协议。', 'The D-Day Landings', 26, 0, 'senior', 'wordlist', 'elective3', 'U3', 'UN peacekeepers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'friction', 'n.', '/ˈfrɪkʃn/', '冲突;摩擦;不和', 'Peacekeepers monitor the peace in areas that have experienced friction.', '维和人员监督那些曾发生冲突地区的和平。', 'The D-Day Landings', 27, 0, 'senior', 'wordlist', 'elective3', 'U3', 'areas of friction', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'disarm', 'v.', '/dɪsˈɑːm/', '解除武装;裁军', 'They worked to disarm combatants and secure their weapons.', '他们努力解除战斗人员的武装并收缴其武器。', 'The D-Day Landings', 28, 0, 'senior', 'wordlist', 'elective3', 'U3', 'disarm combatants', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'combatant', 'n.', '/ˈkɒmbətənt/', '战斗人员;参战者', 'Each combatant was asked to hand over his weapon.', '每名战斗人员都被要求交出武器。', 'The D-Day Landings', 29, 0, 'senior', 'wordlist', 'elective3', 'U3', 'disarm a combatant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'weapon', 'n.', '/ˈwepən/', '武器;兵器', 'The team secured the weapons and removed them from use.', '该小组收缴了武器并使其停止使用。', 'The D-Day Landings', 30, 0, 'senior', 'wordlist', 'elective3', 'U3', 'secure weapons', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ammunition', 'n.', '/ˌæmjʊˈnɪʃn/', '弹药', 'Soldiers carried only as much ammunition as they could lift.', '士兵们只携带他们能扛得动的弹药。', 'The D-Day Landings', 31, 0, 'senior', 'wordlist', 'elective3', 'U3', 'weapons and ammunition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stability', 'n.', '/stəˈbɪlɪti/', '稳固;稳定', 'These measures aim to give stability to conflict zones.', '这些举措旨在为冲突地区带来稳定。', 'The D-Day Landings', 32, 0, 'senior', 'wordlist', 'elective3', 'U3', 'give stability to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'professionalism', 'n.', '/prəˈfeʃnəlɪzm/', '专业素质;职业精神', 'Chinese forces have received praise for their professionalism.', '中国部队因其专业素质而受到赞扬。', 'The D-Day Landings', 33, 0, 'senior', 'wordlist', 'elective3', 'U3', 'praise for professionalism', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'academic', 'adj.', '/ˌækəˈdemɪk/', '学术的;学业的', 'The three universities joined to protect their academic heritage.', '三所大学联合起来保护他们的学术遗产。', 'The D-Day Landings', 34, 0, 'senior', 'wordlist', 'elective3', 'U3', 'academic heritage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'aggression', 'n.', '/əˈɡreʃn/', '侵略;侵犯;攻击性', 'The aggression of the enemy army brought disaster to the country.', '敌军的侵略给这个国家带来了灾难。', 'The D-Day Landings', 35, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an act of aggression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intellectual', 'adj.', '/ˌɪntəˈlektʃʊəl/', '智力的;脑力的;知识的', 'They were determined to save the nation''s intellectual heritage.', '他们决心拯救民族的智识遗产。', 'The D-Day Landings', 36, 0, 'senior', 'wordlist', 'elective3', 'U3', 'intellectual heritage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'emerge', 'v.', '/ɪˈmɜːdʒ/', '出现;浮现;露出', 'Many of China''s leading scholars emerged from that wartime university.', '中国许多顶尖学者都出自那所战时大学。', 'The D-Day Landings', 37, 0, 'senior', 'wordlist', 'elective3', 'U3', 'emerge from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'invader', 'n.', '/ɪnˈveɪdə/', '侵略者;侵略军', 'Many students joined the army to resist the invaders.', '许多学生参军抵抗侵略者。', 'The D-Day Landings', 38, 0, 'senior', 'wordlist', 'elective3', 'U3', 'resist the invaders', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'depict', 'v.', '/dɪˈpɪkt/', '描述;描绘', 'The poet depicted the courage of his peers in a moving poem.', '诗人在一首动人的诗中描绘了同伴们的勇气。', 'The D-Day Landings', 39, 0, 'senior', 'wordlist', 'elective3', 'U3', 'depict the war', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'peer', 'n.', '/pɪə/', '同龄人;同辈;同等地位的人', 'He was admired by his peers for his bravery.', '他因勇敢而受到同辈的敬佩。', 'The D-Day Landings', 40, 0, 'senior', 'wordlist', 'elective3', 'U3', 'among his peers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'glory', 'n.', '/ˈɡlɔːri/', '荣耀;辉煌的成就', 'The university became the crowning glory of the nation''s education.', '这所大学成了民族教育辉煌的顶峰。', 'The D-Day Landings', 41, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the crowning glory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prominent', 'adj.', '/ˈprɒmɪnənt/', '著名的;杰出的;突出的', 'The school was famous for its prominent professors.', '这所学校以其杰出的教授而闻名。', 'The D-Day Landings', 42, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a prominent scholar', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dedication', 'n.', '/ˌdedɪˈkeɪʃn/', '奉献;献身;专注', 'Its spirit of dedication still inspires students today.', '它的奉献精神至今仍激励着学生。', 'The D-Day Landings', 43, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a spirit of dedication', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'representative', 'n.', '/ˌreprɪˈzentətɪv/', '代表;代理人', 'Representatives from four universities gathered to mark the day.', '来自四所大学的代表聚集起来纪念这一天。', 'The D-Day Landings', 44, 0, 'senior', 'wordlist', 'elective3', 'U3', 'send a representative', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'commemorate', 'v.', '/kəˈmeməreɪt/', '纪念;庆祝', 'They gathered to commemorate the soldiers who had died.', '他们聚集起来纪念阵亡的士兵。', 'The D-Day Landings', 45, 0, 'senior', 'wordlist', 'elective3', 'U3', 'commemorate the dead', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anniversary', 'n.', '/ˌænɪˈvɜːsəri/', '周年纪念日', 'In 2017 they marked the 80th anniversary of its founding.', '2017年他们纪念了它建校80周年。', 'The D-Day Landings', 46, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the 80th anniversary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'collective', 'adj.', '/kəˈlektɪv/', '集体的;共同的', 'The story has become part of the nation''s collective memory.', '这个故事已成为民族集体记忆的一部分。', 'The D-Day Landings', 47, 0, 'senior', 'wordlist', 'elective3', 'U3', 'collective memory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sum', 'n.', '/sʌm/', '金额;款项;总数', 'The enemy offered a large sum of money for the hero''s head.', '敌人为这位英雄的人头出了一大笔钱。', 'The D-Day Landings', 48, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a large sum of money', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'grain', 'n.', '/ɡreɪn/', '谷物;粮食;颗粒', 'They found tree bark in his stomach but not a single grain of rice.', '他们在他胃里发现的是树皮,却没有一粒米。', 'The D-Day Landings', 49, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a grain of rice', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'relevant', 'adj.', '/ˈreləvənt/', '有关的;切题的;有意义的', 'The lessons of that war are still relevant to us today.', '那场战争的教训对今天的我们仍有意义。', 'The D-Day Landings', 50, 0, 'senior', 'wordlist', 'elective3', 'U3', 'still relevant today', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u3.01', '①集合名词作主语(看作整体用单数 / 强调成员用复数)', 'A2', 12, '外研社版选择性必修第三册 U3 — army/enemy/team/crew/government/crowd/committee/jury/staff/nation 等集合名词:看作一个整体(常带 it / as one body / whole)时谓语用单数;强调内部成员各自动作(常带 their / themselves / among themselves / 复数代词)时用复数。police/people 等通常作复数。', 1, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u3.02', '②and 连接的主语(两者用复数 / 同一整体用单数)', 'A2', 12, '外研社版选择性必修第三册 U3 — and 连接两个不同的人或物 → 复数(常各带冠词或 both…and…);指同一个人/同一事物或固定搭配(bread and butter、war and peace、the general and commander 同指一人、aim and purpose 同一概念) → 单数。', 2, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u3.03', '③each/every/either/neither 与 a number of / the number of(含就近原则)', 'A2', 12, '外研社版选择性必修第三册 U3 — each/every/either/neither + 单数;every…and every… 与 many a + 单数。a number of + 复数,the number of + 单数。neither…nor…/either…or… 遵循就近原则(谓语与最近的主语一致)。', 3, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The whole army ____ ready to move the moment the order came.', 'was', 'were', 'have', 'do', 'A', 'army 由 whole 强调为一个整体,看作单数,过去时用 was。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The enemy ____ hiding in their hundreds along the top of the cliffs.', 'was', 'were', 'has', 'is', 'B', 'their hundreds 说明把 enemy 看作分散行动的成员,用复数 were。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'Acting as one body, the government ____ decided to keep the date a secret.', 'have', 'are', 'has', 'were', 'C', 'as one body 把 government 视为整体,用单数 has decided。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The small rescue team ____ led by a single captain who had survived Omaha Beach.', 'were', 'have', 'are', 'was', 'D', '由一名队长统领,team 作整体看,过去被动用 was led。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'Working as one, the crew ____ able to reach the beach safely.', 'was', 'were', 'have', 'do', 'A', 'as one 强调 crew 为一个整体,用单数 was。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The crew ____ divided among themselves about which route to take.', 'was', 'were', 'has', 'is', 'B', 'among themselves 表明成员各持己见,用复数 were。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The planning committee ____ made up of officers from three countries.', 'were', 'have', 'was', 'do', 'C', 'be made up of 把 committee 当作一个整体,用单数 was made up of。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The committee ____ still arguing among themselves at midnight.', 'was', 'has', 'is', 'were', 'D', 'among themselves 强调成员之间各自争论,用复数 were。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The frightened crowd on the sand ____ unable to move, like one terrified mass.', 'was', 'were', 'have', 'are', 'A', 'one terrified mass 把 crowd 看作整体,用单数 was。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The crowd ____ waving their flags and cheering the soldiers home.', 'was', 'were', 'has', 'is', 'B', 'their flags 表明强调人群中的成员,用复数 were。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The ship''s company ____ proud of what it had achieved that day.', 'were', 'have', 'was', 'do', 'C', '后文用 it 指代,说明把 company 看作整体,用单数 was。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The team of nurses ____ doing their best to save every wounded man.', 'was', 'has', 'is', 'were', 'D', 'their best 表明强调护士们各自的努力,用复数 were。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'Your enemy ____ a single, well-trained force that fights as one.', 'is', 'are', 'have', 'do', 'A', 'a single force / fights as one 把 enemy 看作一个整体,现在时用单数 is。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The jury at the war trial ____ unable to agree among themselves.', 'was', 'were', 'has', 'is', 'B', 'among themselves 强调陪审团成员意见不一,用复数 were。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The jury ____ going to give its verdict tomorrow morning.', 'are', 'have', 'is', 'do', 'C', 'its verdict 用 it 指代,把 jury 看作整体,用单数 is。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The staff at the field hospital ____ doing their jobs without any rest.', 'was', 'has', 'is', 'were', 'D', 'their jobs 强调工作人员各自忙碌,用复数 were。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The whole nation ____ grateful to the soldiers who had set it free.', 'was', 'were', 'have', 'are', 'A', 'whole nation 及后文 it 把国家看作整体,用单数 was。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The police ____ still searching the ruined streets for hidden weapons.', 'was', 'were', 'has', 'does', 'B', 'police 通常作复数对待,用复数 were。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'The group of survivors ____ growing smaller as one by one its members pass away.', 'are', 'have', 'is', 'do', 'C', 'its members 用 it 指代,把 group 看作整体,用单数 is。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.01'), 'Moving as one, the band ____ marching slowly past the war memorial.', 'are', 'have', 'do', 'is', 'D', 'as one 强调乐队整体行进,用单数 is。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Britain and Canada ____ among the Allied nations that joined the landings.', 'were', 'was', 'has', 'is', 'A', 'Britain and Canada 是两个国家,主语为复数,用 were。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Bread and butter ____ often all the soldiers had to eat at dawn.', 'were', 'was', 'have', 'do', 'B', 'bread and butter 是一道食品的固定搭配,指同一事物,用单数 was。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The general and commander of the whole operation ____ the same man, Eisenhower.', 'were', 'have', 'was', 'are', 'C', 'the general and commander 只用一个冠词、同指一人,用单数 was。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The general and the sergeant ____ arguing about when to attack.', 'was', 'has', 'is', 'were', 'D', '两个冠词说明是两个人,主语为复数,用 were。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'War and peace ____ the great theme running through this unit.', 'is', 'are', 'have', 'do', 'A', 'war and peace 在此指同一个主题概念,用单数 is。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The captain and the sergeant ____ both wounded on the beach.', 'was', 'were', 'has', 'is', 'B', 'both 和两个冠词都说明是两个人,用复数 were。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Their courage and their devotion ____ still remembered today.', 'is', 'has', 'are', 'does', 'C', '重复的 their 表明是两种品质,主语为复数,用 are。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Fish and chips ____ the simple meal the soldiers missed most.', 'were', 'have', 'do', 'was', 'D', 'fish and chips 是一道菜的固定搭配,指同一事物,用单数 was。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The poet and soldier Laurence Binyon ____ written these famous lines.', 'has', 'have', 'are', 'were', 'A', 'the poet and soldier 同指 Binyon 一人,用单数 has written。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The sea and the sky ____ both grey on the morning of the attack.', 'was', 'were', 'has', 'is', 'B', 'the sea and the sky 是两样事物,加 both,用复数 were。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Law and order ____ slowly returning to the liberated towns.', 'were', 'have', 'was', 'do', 'C', 'law and order 是表示同一概念的固定搭配,用单数 was。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Paris and the towns around it ____ freed by the end of August.', 'was', 'has', 'is', 'were', 'D', 'Paris 与周边城镇是多处地点,主语为复数,用 were。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The needle and thread ____ all the nurse had to close the wound.', 'was', 'were', 'have', 'do', 'A', 'needle and thread 作针线这一整体工具,用单数 was。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Eisenhower and his officers ____ confident of a full victory.', 'was', 'were', 'has', 'is', 'B', 'Eisenhower 与众军官是多个人,主语为复数,用 were。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The aim and purpose of Operation Overlord ____ to free Europe.', 'were', 'have', 'was', 'do', 'C', 'aim and purpose 指同一个目的,用单数 was。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'Both the army and the navy ____ needed for the landings to succeed.', 'was', 'has', 'is', 'were', 'D', 'both…and… 连接两支部队,主语为复数,用 were。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The moon and the tide ____ studied for weeks before the date was chosen.', 'were', 'was', 'has', 'is', 'A', 'the moon and the tide 是两样事物,主语为复数,用 were。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The horror and the violence of that day ____ never forgotten by the survivors.', 'was', 'were', 'has', 'is', 'B', '重复冠词的 horror and violence 是两件事,主语为复数,用 were。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'His wife and his children ____ waiting at home for news of him.', 'was', 'has', 'were', 'is', 'C', 'wife 与 children 是不同的人,主语为复数,用 were。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.02'), 'The cruelty and the waste of war ____ shown clearly in the film.', 'is', 'has', 'does', 'are', 'D', '重复冠词说明 cruelty 与 waste 是两件事,主语为复数,用 are。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Each of the soldiers ____ given a parachute before the night jump.', 'was', 'were', 'have', 'are', 'A', 'each of + 复数名词,谓语仍用单数,过去被动用 was given。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Every man and woman in the unit ____ a part to play in the plan.', 'have', 'had', 'were', 'are', 'B', 'every…and every/every…and… 结构作单数,过去用 had。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'A number of boats ____ hit by enemy fire that morning.', 'was', 'has', 'were', 'is', 'C', 'a number of + 复数名词,谓语用复数 were。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'The number of casualties ____ rising hour by hour.', 'were', 'have', 'are', 'was', 'D', 'the number of 作主语指“数目”,用单数 was。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Neither of the two plans ____ perfect, but one had to be chosen.', 'was', 'were', 'have', 'are', 'A', 'neither of + 复数名词,谓语用单数 was。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Either of these narrow routes ____ likely to be defended by the enemy.', 'are', 'is', 'have', 'do', 'B', 'either of + 复数名词,谓语用单数 is。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Each soldier on the boat ____ his own heavy pack to carry.', 'have', 'were', 'had', 'are', 'C', 'each + 单数名词作主语,谓语用单数,过去用 had。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'A number of survivors ____ still meeting every year to remember that day.', 'is', 'has', 'does', 'are', 'D', 'a number of + 复数名词,谓语用复数 are。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'The number of veterans who attend ____ smaller each year.', 'is', 'are', 'have', 'do', 'A', 'the number of 指“数目”,作单数,用 is。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Every order from the commander ____ to be obeyed at once.', 'have', 'had', 'were', 'are', 'B', 'every + 单数名词作主语,谓语用单数,过去用 had to。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Neither the captain nor his men ____ willing to give up the beach.', 'was', 'has', 'were', 'is', 'C', 'neither…nor… 遵循就近原则,靠近 men(复数),用 were。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Neither the men nor their captain ____ willing to retreat.', 'were', 'have', 'are', 'was', 'D', 'neither…nor… 就近原则,靠近 captain(单数),用 was。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Either the general or his officers ____ going to make the final call.', 'are', 'is', 'has', 'does', 'A', 'either…or… 就近原则,靠近 officers(复数),用 are。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Either the officers or the general ____ going to make the final call.', 'are', 'is', 'have', 'does', 'B', 'either…or… 就近原则,靠近 general(单数),用 is。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Each of the landing boats ____ carrying about thirty men.', 'were', 'have', 'was', 'are', 'C', 'each of + 复数名词,谓语用单数,过去进行用 was carrying。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'A large number of weapons ____ collected and locked away after the war.', 'was', 'has', 'is', 'were', 'D', 'a large number of + 复数名词,谓语用复数 were。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'The number of weapons handed in ____ greater than anyone had expected.', 'was', 'were', 'have', 'are', 'A', 'the number of 指“数目”,作单数,用 was。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Every soldier and every nurse ____ remembered at the yearly ceremony.', 'are', 'is', 'have', 'do', 'B', 'every…and every… 结构作单数,被动用 is remembered。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Neither of the brothers ____ able to forget the bombing of their city.', 'were', 'have', 'was', 'are', 'C', 'neither of + 复数名词,谓语用单数 was。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U3' AND code='fe3u3.03'), 'Many a young man ____ marched to the front and never returned.', 'have', 'are', 'were', 'has', 'D', 'many a + 单数名词作主语,谓语用单数 has marched。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Largest Operation in History', 'By the spring of 1944, the Second World War had raged across the world for nearly five years. Along the south coast of England, however, something unusual was taking shape. Allied troops, made up mainly of British, Canadian and American soldiers, were quietly gathering in huge numbers. This was the final stage of a top-secret plan code-named Operation Overlord, the largest combined sea, air and land operation the world had ever seen. Its aim was to free north-west Europe from enemy occupation. After commanders had waited for the perfect mix of weather, moon and tide, the start was set for the sixth of June. At dawn that day, thousands of men dropped by parachute behind enemy lines, while thousands more crossed the English Channel towards the beaches of Normandy. Few of them could have imagined the violence that waited on the sand. Yet within weeks their courage had begun to change the course of the war in Europe.', '说明·诺曼底登陆概览', 158, '[{"q":"Why were Allied troops gathering along the south coast of England?","answer":"A","options":["To get ready for a secret landing in Europe.","To defend England from an enemy invasion.","To begin a training march across the country.","To wait for the war to end on its own."],"explanation":"正文说他们是为代号 Overlord 的登陆计划集结,选项转述了“准备秘密登陆”这一目的。"},{"q":"What decided the exact date when the operation would begin?","answer":"B","options":["The arrival of new American soldiers.","Commanders waited for ideal natural conditions.","A direct order from the British king.","The end of the fighting in the east."],"explanation":"正文说指挥官等待天气、月相和潮水的最佳组合,即理想的自然条件。"},{"q":"What does the passage suggest about the soldiers who landed?","answer":"A","options":["They faced far more danger than they had expected.","They found the beaches empty and quiet.","They quickly gave up and returned home.","They were all experienced in beach landings."],"explanation":"“few could have imagined the violence”暗示登陆远比他们预想的危险。"}]'::jsonb, '[{"word":"Allied","cn":"同盟国的"},{"word":"parachute","cn":"降落伞"},{"word":"occupation","cn":"占领"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Fight at Omaha Beach', 'The hardest fighting of D-Day took place at Omaha Beach. Long before the boats reached the shore, the enemy were hiding above the sand, waiting in their gun positions. As the first soldiers tried to land, heavy machine-gun fire swept across the water. Some boats were hit and sank, and many men drowned under the weight of their packs before they ever touched the beach. Those who did reach the shore had to cross open ground with bombs falling all around them. By the middle of the morning, hundreds lay dead in the shallow water and among the tanks on the sand. One survivor later remembered being the first man out of his boat. The next soldier to cross the beach safely was the seventh; everyone in between was hit. Two of them were killed and three were wounded. That, he said, was how lucky a man had to be simply to stay alive on that terrible morning.', '记叙·奥马哈海滩的激战', 158, '[{"q":"Why did many soldiers drown before reaching the beach?","answer":"B","options":["They had never learned how to swim.","Their heavy packs pulled them down when the boats sank.","The sea water was far too cold to bear.","They jumped into the water on purpose to hide."],"explanation":"正文说很多人因背包过重在船沉时淹死,选项转述了这一原因。"},{"q":"What did the survivor''s story about the seventh man show?","answer":"C","options":["Most soldiers crossed the beach without any harm.","The seventh soldier was the bravest of them all.","Staying alive on the beach was largely a matter of luck.","Leaving the boats was perfectly safe."],"explanation":"“that''s how lucky you had to be”说明活下来主要靠运气。"},{"q":"Which best describes the scene by the middle of the morning?","answer":"D","options":["The fighting had already stopped.","The enemy had completely disappeared.","The soldiers were resting safely on the sand.","The beach was covered with the dead and the wounded."],"explanation":"正文写到上午中段海滩上躺满死伤者,选项概括了这一场景。"}]'::jsonb, '[{"word":"drown","cn":"淹死"},{"word":"gunfire","cn":"炮火"},{"word":"tank","cn":"坦克"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Planning Operation Overlord', 'The success of D-Day depended on months, perhaps years, of careful planning, and nothing about the operation could be left to chance. The whole plan was kept top secret, for if the enemy had learned where the Allies meant to land, the attack would have failed before it began. Commanders studied maps of the French coast and chose Normandy rather than the ports that the enemy expected. They also had to wait for nature itself. The landing needed calm seas, enough moonlight for the parachute drops, and a low tide that would expose the enemy''s beach defences. Such conditions came together for only a few days each month. In early June the weather suddenly turned stormy, and the commanders faced a hard choice: wait, or risk everything. Trusting a forecast of a brief clear spell, General Eisenhower gave the order to go. It was one of the boldest decisions of the entire war, and in the end it paid off.', '说明·登陆的策划与抉择', 160, '[{"q":"Why was the plan kept top secret?","answer":"A","options":["So that the enemy would not know where the landing would happen.","Because the soldiers did not trust one another.","So that the news would surprise the British public.","Because the exact date had not yet been chosen."],"explanation":"正文说若敌人得知登陆地点,进攻会失败,故保密是为不让敌人知道地点。"},{"q":"Why did the Allies choose Normandy for the landing?","answer":"B","options":["It had the largest ports in all of France.","It was not where the enemy was expecting them.","It was the closest point to England.","It had already been freed from the enemy."],"explanation":"正文说他们选诺曼底而非敌人预期的港口,即出敌不意。"},{"q":"What made Eisenhower''s final order so difficult?","answer":"C","options":["He had been told the enemy had already surrendered.","His soldiers refused to cross the Channel.","Bad weather forced him to gamble on an uncertain forecast.","He had to attack with no planning at all."],"explanation":"正文说天气突变,他只能信一个短暂晴天的预报冒险下令,故抉择艰难。"}]'::jsonb, '[{"word":"tide","cn":"潮水"},{"word":"forecast","cn":"天气预报"},{"word":"commander","cn":"指挥官"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'We Will Remember Them', 'Seventy years after D-Day, the men who had fought there gathered once more on both sides of the English Channel. They were old now, and fewer in number with every passing year, but they came to remember the friends they had lost on the beaches of northern France. Crowds joined them for solemn memorial ceremonies. At one of these, a former soldier read aloud some lines from a poem called For the Fallen, written by Laurence Binyon during an earlier war. The poem promises that the young men who died will never grow old as the living do, and that time will not wear them away. At the setting of the sun and in the morning, it says, we will remember them. For the survivors, such words carry a heavy meaning. Each year a few more of them are gone, yet their outstanding courage means that they, and those who never came home, will always be remembered.', '记叙·纪念与《为阵亡者》', 157, '[{"q":"Why did the old soldiers return to the Channel after seventy years?","answer":"D","options":["To take part in the fighting once again.","To find the homes they once lived in.","To train a new group of young soldiers.","To honour the comrades who had died there."],"explanation":"正文说他们回来纪念失去的战友,选项转述了这一目的。"},{"q":"What does the poem For the Fallen promise about the dead?","answer":"A","options":["They will stay forever young in people''s memory.","They will one day return to their families.","They will slowly be forgotten over time.","They will grow old just like the living."],"explanation":"诗句说阵亡者不会像生者那样变老,即在记忆中永远年轻。"},{"q":"What is the main message of the last part of the passage?","answer":"B","options":["War heroes are quickly forgotten by all.","The soldiers'' bravery keeps their memory alive.","Only the survivors deserve to be remembered.","The ceremonies have now come to an end."],"explanation":"末段说他们杰出的勇敢使他们永被铭记,故主旨是勇气让记忆长存。"}]'::jsonb, '[{"word":"memorial","cn":"纪念的"},{"word":"solemn","cn":"庄重的"},{"word":"outstanding","cn":"杰出的"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Keeping the Peace', 'The cruelty of war is reason enough to do everything possible to prevent it, and this belief lies behind the United Nations'' many peacekeeping missions. Peacekeepers are sent to regions that have suffered conflict and civil war, where their job is to watch over the peace and make sure that sides which once fought now keep to their agreements. They help to disarm fighters and to collect weapons and ammunition so that these can no longer be used. Such steps are meant to bring stability to troubled areas and to allow governments to rebuild their authority. China now plays a growing part in this work. It has trained eight thousand troops who stay ready for United Nations missions at any time. In conflict zones around the world, Chinese peacekeepers are highly valued, and they have won praise for their professionalism. Through such efforts, the world tries to make sure that the horrors of the past are not repeated.', '说明·联合国维和与中国', 158, '[{"q":"What is the main job of UN peacekeepers?","answer":"C","options":["To win wars on behalf of the United Nations.","To sell weapons to local governments.","To help former enemies keep the peace they have agreed to.","To train new soldiers for future battles."],"explanation":"正文说维和人员确保曾交战的各方遵守协议,即帮助维持已达成的和平。"},{"q":"How does China take part in peacekeeping?","answer":"D","options":["It sends money but never any people.","It only watches the missions from a distance.","It has refused to join such missions.","It keeps thousands of trained troops ready for UN missions."],"explanation":"正文说中国训练了八千名随时待命的维和部队。"},{"q":"Why are Chinese peacekeepers respected abroad?","answer":"A","options":["They carry out their duties in a highly professional way.","They fight harder than anyone else does.","They bring their own weapons to sell.","They stay only in completely safe areas."],"explanation":"正文说他们因专业素质受到赞扬,选项转述了这一点。"}]'::jsonb, '[{"word":"peacekeeper","cn":"维和人员"},{"word":"disarm","cn":"解除武装"},{"word":"stability","cn":"稳定"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Lianda: A University at War', 'In 1937 the aggression of an invading army brought disaster to three of China''s greatest universities. Two of them were occupied and one was destroyed by bombing. To save their academic and intellectual heritage, the three schools joined together far away in Kunming, forming a single new university known as Lianda. Getting there meant an epic journey of more than two thousand kilometres, much of it on foot. Life at Lianda was desperately hard. Students slept packed together in rough buildings and went short of food, books and equipment. Classes were often broken up by air attacks and had to be held in the early morning or late afternoon. Yet over eight long years the spirit and belief of its teachers and students kept the nation''s learning alive. Many of China''s finest scholars later emerged from Lianda, including two future Nobel Prize winners. The school is now physically gone, but its story of passion and dedication has become part of the nation''s collective memory.', '记叙·战火中的西南联大', 164, '[{"q":"Why did the three universities join together as Lianda?","answer":"B","options":["To make a single larger sports team.","To protect their learning after the invasion.","To move closer to the capital city.","To avoid paying for any new buildings."],"explanation":"正文说三校为保住学术与智识遗产而联合,选项转述了这一原因。"},{"q":"What were conditions like for students at Lianda?","answer":"C","options":["They enjoyed comfortable rooms and plenty of food.","They rarely had any lessons at all.","They lived and studied under very harsh conditions.","They were kept safe far from any danger."],"explanation":"正文描写住简陋房屋、缺粮缺书、常遭空袭,可概括为条件艰苦。"},{"q":"Why is Lianda still remembered today?","answer":"D","options":["It still has the finest buildings in China.","It produced the country''s richest businessmen.","It was never actually touched by the war.","Its spirit of dedication left a lasting mark on the nation."],"explanation":"正文说它的热情与奉献已成为民族集体记忆,故仍被铭记。"}]'::jsonb, '[{"word":"aggression","cn":"侵略"},{"word":"intellectual","cn":"智识的"},{"word":"dedication","cn":"奉献"}]'::jsonb, 2, 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'A Review of Saving Private Ryan', 'Saving Private Ryan is a war film (1)____ by Steven Spielberg. It tells the story of a group of American soldiers who are (2)____ into the French countryside to find one man. James Ryan is the only one of four brothers still (3)____, and the army decides to bring him home. The rescue team is (4)____ by Captain Miller, a brave survivor of the Omaha Beach battle. At the start of the film, the audience is (5)____ straight into thirty terrible minutes that show the landings in Normandy. We see the full (6)____ of war: the noise, the chaos and the senseless (7)____ of life. Yet the film is also a story of (8)____ and sacrifice. The message is (9)____: we want peace, not war. It is a film that no one who watches it can easily (10)____.', 138, 2, '[{"q":"1","answer":"A","options":["directed","cooked","planted","repaired"],"explanation":"导演电影用 direct,a film directed by。"},{"q":"2","answer":"B","options":["born","sent","grown","fallen"],"explanation":"被派去用 be sent into。"},{"q":"3","answer":"C","options":["asleep","awake","alive","afraid"],"explanation":"四兄弟中唯一还活着的,still alive。"},{"q":"4","answer":"D","options":["lost","paid","sold","led"],"explanation":"队伍由队长率领,be led by。"},{"q":"5","answer":"A","options":["thrown","fed","planted","cleaned"],"explanation":"观众被猛然带入,be thrown into。"},{"q":"6","answer":"B","options":["joy","horror","peace","comfort"],"explanation":"战争全部的恐怖,the full horror of war。"},{"q":"7","answer":"C","options":["gift","growth","waste","supply"],"explanation":"对生命无谓的浪费,senseless waste of life。"},{"q":"8","answer":"D","options":["money","music","fashion","courage"],"explanation":"勇气与牺牲的故事,courage and sacrifice。"},{"q":"9","answer":"A","options":["simple","funny","sweet","tasty"],"explanation":"信息很简单,the message is simple。"},{"q":"10","answer":"B","options":["enjoy","forget","repeat","miss"],"explanation":"没人能轻易忘记,can easily forget。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'The Bombing of Chongqing', 'During the Second World War, the city of Chongqing (1)____ terribly. The enemy bombed it more than two hundred (2)____ over five and a half years. The (3)____ of these attacks was to destroy the spirit of ordinary people and stop them from (4)____ the war effort. Thousands of (5)____ were killed, and many families lost their homes. Old people in the city still (6)____ how they ran into shelters when the warning sounded. They waited in the dark, (7)____ for the bombing to stop. Yet the terror from the sky did not break their (8)____ to fight on. Today an air-raid warning is sounded every year to (9)____ those who died. It also reminds the living never to (10)____ the price of war and the value of peace.', 129, 2, '[{"q":"1","answer":"C","options":["smiled","travelled","suffered","danced"],"explanation":"城市遭受苦难,suffer terribly。"},{"q":"2","answer":"D","options":["hours","miles","songs","times"],"explanation":"两百多次,two hundred times。"},{"q":"3","answer":"A","options":["purpose","gift","garden","price"],"explanation":"袭击的目的,the purpose of。"},{"q":"4","answer":"B","options":["leaving","supporting","building","washing"],"explanation":"阻止他们支持战事,stop from supporting。"},{"q":"5","answer":"C","options":["winners","tourists","civilians","singers"],"explanation":"成千上万平民被炸死,thousands of civilians。"},{"q":"6","answer":"D","options":["forget","deny","doubt","remember"],"explanation":"老人仍记得,still remember how。"},{"q":"7","answer":"A","options":["waiting","laughing","marching","cooking"],"explanation":"在黑暗中等待轰炸停止,waiting for。"},{"q":"8","answer":"B","options":["fear","determination","fortune","fashion"],"explanation":"没能摧毁他们继续战斗的决心,determination to fight。"},{"q":"9","answer":"C","options":["forget","sell","honour","hide"],"explanation":"为纪念逝者,to honour those who died。"},{"q":"10","answer":"D","options":["learn","share","count","forget"],"explanation":"提醒生者永不忘记战争的代价,never to forget。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'Yang Jingyu, a War Hero', 'Yang Jingyu was a famous (1)____ who fought the invaders in north-east China. In 1938 the enemy offered a large (2)____ of money for his head, and a great number of troops were sent to (3)____ his men. Facing a serious (4)____ of food and supplies, Yang told his soldiers to break out in small groups. He himself (5)____ on alone for five days in the deep snow. He killed more than twenty enemy soldiers (6)____ he finally died. When the enemy cut open his (7)____, they found only tree bark, cotton and grass roots — not a single (8)____ of rice. His death was a heavy (9)____ to his men, but they turned their sorrow into anger and went on (10)____ the invaders even more fiercely.', 127, 2, '[{"q":"1","answer":"A","options":["hero","farmer","singer","doctor"],"explanation":"一位著名的英雄,a famous hero。"},{"q":"2","answer":"B","options":["piece","sum","drop","sheet"],"explanation":"一大笔钱,a large sum of money。"},{"q":"3","answer":"C","options":["paint","feed","surround","thank"],"explanation":"被派去包围他的部下,sent to surround。"},{"q":"4","answer":"D","options":["supply","gift","store","shortage"],"explanation":"严重缺乏粮食物资,a shortage of。"},{"q":"5","answer":"A","options":["fought","slept","sang","rested"],"explanation":"独自战斗了五天,fought on alone。"},{"q":"6","answer":"B","options":["because","before","unless","although"],"explanation":"在最终牺牲之前,before he died。"},{"q":"7","answer":"C","options":["book","boat","body","box"],"explanation":"剖开他的身体,cut open his body。"},{"q":"8","answer":"D","options":["glass","group","gate","grain"],"explanation":"没有一粒米,a single grain of rice。"},{"q":"9","answer":"A","options":["blow","gift","prize","joke"],"explanation":"对部下沉重的打击,a heavy blow。"},{"q":"10","answer":"B","options":["feeding","fighting","painting","cooking"],"explanation":"继续战斗,go on fighting。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'A Letter from the Front', 'My dearest mother, I am writing this letter by the light of a small (1)____ in our tent. It is hard to (2)____ what these days have been like. The fighting is fierce, and (3)____ of us have been wounded. Yet I want you not to (4)____ about me too much. We are all (5)____ to each other like brothers, and that gives me (6)____. Last week our whole unit (7)____ as one to carry the wounded to safety. I think often of home, of the quiet (8)____ where we used to walk. When this war is finally (9)____, I will come back to you. Until then, please keep my room as it is, and tell my little sister that I have not (10)____ her. Your loving son, Tom.', 129, 2, '[{"q":"1","answer":"C","options":["river","mountain","candle","cloud"],"explanation":"借着小蜡烛的光,the light of a candle。"},{"q":"2","answer":"D","options":["count","sell","win","describe"],"explanation":"很难描述,hard to describe。"},{"q":"3","answer":"A","options":["many","much","every","each"],"explanation":"我们中许多人受了伤,many of us have been。"},{"q":"4","answer":"B","options":["hear","worry","write","learn"],"explanation":"别太担心我,not to worry about。"},{"q":"5","answer":"C","options":["cruel","strange","close","silent"],"explanation":"像兄弟般亲密,close to each other。"},{"q":"6","answer":"D","options":["money","trouble","fear","strength"],"explanation":"这给我力量,gives me strength。"},{"q":"7","answer":"A","options":["worked","slept","played","sang"],"explanation":"整个小队齐心协力,worked as one。"},{"q":"8","answer":"B","options":["weapons","fields","tanks","bombs"],"explanation":"我们曾散步的安静田野,the quiet fields。"},{"q":"9","answer":"C","options":["open","busy","over","late"],"explanation":"当战争终于结束,the war is over。"},{"q":"10","answer":"D","options":["found","called","taught","forgotten"],"explanation":"我没有忘记她,have not forgotten her。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'Visiting the War Museum', 'Last spring our class visited a war (1)____ in the city. At the entrance stood an old (2)____, still wearing the uniform he had worn as a young man. He had (3)____ in the war seventy years before. Inside, glass cases were (4)____ of letters, photographs and worn-out boots. One photograph (5)____ a line of soldiers marching towards the sea. Our guide spoke in a (6)____ voice as she told us their story. She said that many of them had (7)____ their lives on the beaches. By the end of the visit, the room had grown (8)____, and some of my classmates were close to tears. I understood then why we must (9)____ such people. Peace, our teacher said, is something we should never take for (10)____.', 127, 2, '[{"q":"1","answer":"A","options":["museum","kitchen","garden","market"],"explanation":"参观战争博物馆,a war museum。"},{"q":"2","answer":"B","options":["teacher","soldier","farmer","driver"],"explanation":"一位身着军装的老兵,an old soldier。"},{"q":"3","answer":"C","options":["danced","cooked","fought","painted"],"explanation":"曾在战争中作战,had fought in。"},{"q":"4","answer":"D","options":["afraid","ready","proud","full"],"explanation":"玻璃柜里装满信件,were full of。"},{"q":"5","answer":"A","options":["showed","ate","drove","sold"],"explanation":"一张照片展示了一队士兵,a photograph showed。"},{"q":"6","answer":"B","options":["happy","quiet","angry","hungry"],"explanation":"用低沉安静的声音,a quiet voice。"},{"q":"7","answer":"C","options":["found","sold","lost","washed"],"explanation":"许多人在海滩上失去了生命,had lost their lives。"},{"q":"8","answer":"D","options":["bright","warm","busy","silent"],"explanation":"房间变得安静,had grown silent。"},{"q":"9","answer":"A","options":["remember","forget","ignore","blame"],"explanation":"为何必须铭记这些人,must remember。"},{"q":"10","answer":"B","options":["sale","granted","free","gold"],"explanation":"决不能把和平视为理所当然,take for granted。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'A Garden for Peace', 'In the centre of our town there is a small (1)____ garden. It was built to remember the young men who (2)____ during the two world wars. In spring the trees are (3)____ of white flowers, and the air is calm and sweet. Every November people (4)____ there to lay flowers beside a stone wall. On the wall are (5)____ the names of those who never returned. My grandfather often takes me there. He says it is important for the young to (6)____ what war really costs. Standing in that quiet place, I find it hard to (7)____ that such gentle ground was once linked to so much pain. The garden teaches a simple (8)____: that peace is precious and must be (9)____. Each time I leave, I feel both sad and (10)____, and I promise myself to help keep the peace.', 142, 2, '[{"q":"1","answer":"C","options":["sports","fruit","peace","fire"],"explanation":"一座和平花园,a peace garden。"},{"q":"2","answer":"D","options":["won","sang","slept","died"],"explanation":"在两次世界大战中牺牲的年轻人,who died。"},{"q":"3","answer":"A","options":["full","afraid","ready","sorry"],"explanation":"树上开满白花,full of white flowers。"},{"q":"4","answer":"B","options":["hide","gather","shout","run"],"explanation":"人们聚集献花,people gather there。"},{"q":"5","answer":"C","options":["eaten","driven","carved","washed"],"explanation":"墙上刻着名字,are carved the names。"},{"q":"6","answer":"D","options":["forget","doubt","deny","understand"],"explanation":"让年轻人明白战争的代价,to understand。"},{"q":"7","answer":"A","options":["believe","count","sell","build"],"explanation":"很难相信这片土地曾与痛苦相连,hard to believe。"},{"q":"8","answer":"B","options":["price","lesson","game","meal"],"explanation":"教给人一个简单的道理,a simple lesson。"},{"q":"9","answer":"C","options":["sold","wasted","protected","hidden"],"explanation":"和平珍贵,必须被守护,must be protected。"},{"q":"10","answer":"D","options":["hungry","sleepy","bored","hopeful"],"explanation":"既悲伤又满怀希望,sad and hopeful。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Interview with a D-Day Veteran', '外研社版选择性必修第三册 U3 · 对话:记者采访登陆日老兵', 3, 'A: Thank you for talking to us, Mr Brown. How old were you on the day of the landings?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'A Parachute in the Museum', '外研社版选择性必修第三册 U3 · 独白:博物馆讲解员介绍降落伞', 2, 'Welcome to the war museum. In front of you is a real parachute used during the Normandy landings. It belonged to a young soldier who dropped behind enemy lines before dawn. Notice how thin and light the silk is; men trusted their lives to it. Next to it you can see his torn uniform and a letter he wrote to his mother the night before the jump. Please look, but do not touch. These objects are over eighty years old, and they help us remember how much these young men gave.', '博物馆讲解员介绍眼前一具真实的诺曼底登陆用降落伞。它属于一名黎明前空降到敌后的年轻士兵。请注意伞布多么薄而轻,士兵们却把性命托付给它。旁边是他破损的军装,以及他在跳伞前夜写给母亲的信。只能看,不能触摸。这些物品已有八十多年,提醒人们这些年轻人付出了多少。', 'uk_female', '[{"q":"What is the main object the guide describes?","type":"choice","answer":"D","options":["A modern fighter plane.","A stone war memorial.","A wooden fishing boat.","A parachute from the Normandy landings."]},{"q":"Who did the parachute belong to?","type":"choice","answer":"A","options":["A young soldier who dropped behind enemy lines.","A famous general.","The museum''s first owner.","A local fisherman."]},{"q":"What is shown next to the parachute?","type":"choice","answer":"B","options":["A map of the whole world.","His uniform and a letter to his mother.","A box of medals.","A model of a tank."]},{"q":"What are visitors asked not to do?","type":"choice","answer":"C","options":["Take any photographs.","Speak to the guide.","Touch the objects.","Sit on the chairs."]},{"q":"Why does the guide say the objects matter?","type":"choice","answer":"D","options":["They are worth a lot of money.","They were made very recently.","They belong to the guide herself.","They help people remember the soldiers'' sacrifice."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Choosing a Book About the War', '外研社版选择性必修第三册 U3 · 对话:两名学生选读战争书籍', 3, 'A: Our teacher wants each of us to read a book about the war and write a review. Have you chosen one yet?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Notice About the Memorial March', '外研社版选择性必修第三册 U3 · 独白:广播通知纪念游行安排', 2, 'Good evening. Here is a notice about this Sunday''s memorial march. The march will begin at ten o''clock in the morning at the town hall and end at the peace garden. Veterans and their families will lead the way, followed by the local schools. Roads in the town centre will be closed from nine until noon, so please leave your car at home and come on foot. After the march, there will be a short ceremony at the stone wall, where flowers may be laid. Everyone is warmly welcome to take part.', '晚间广播通知本周日纪念游行安排:游行上午十点从市政厅出发,到和平花园结束。老兵及家属走在最前,随后是当地学校。市中心道路九点至中午封闭,请把车留在家中、步行前来。游行后会在石墙前举行简短仪式,可献花。欢迎人人参加。', 'uk_female', '[{"q":"When will the memorial march begin?","type":"choice","answer":"B","options":["At nine in the evening.","At ten in the morning.","At noon.","At dawn."]},{"q":"Where will the march end?","type":"choice","answer":"C","options":["At the railway station.","At the seaside.","At the peace garden.","At the school gate."]},{"q":"Who will lead the march?","type":"choice","answer":"D","options":["The police band.","A group of tourists.","The town''s shopkeepers.","Veterans and their families."]},{"q":"What are people asked to do about their cars?","type":"choice","answer":"A","options":["Leave them at home and walk.","Park them at the town hall.","Drive slowly through the centre.","Lend them to the veterans."]},{"q":"What can people do at the stone wall?","type":"choice","answer":"B","options":["Buy tickets.","Lay flowers.","Have lunch.","Play music."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'Why We Study War History', '外研社版选择性必修第三册 U3 · 对话:师生讨论学习战争历史的意义', 3, 'A: Sir, why do we have to learn so much about old wars? They happened long ago.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'A Speech at a Peace Event', '外研社版选择性必修第三册 U3 · 独白:和平纪念活动上的简短讲话', 2, 'Friends, we have gathered here today not to celebrate war but to honour peace. Eighty years ago, young men left these very streets and never returned. They did not die so that we could forget; they died so that we could live in freedom. Every flower we lay today is a promise that their courage will be remembered. Let us teach our children that peace is precious and easily lost. And let us work, each in our own way, to make sure that such suffering never comes again. Thank you.', '演讲者在和平纪念活动上说:今天聚在这里不是为颂扬战争,而是为礼赞和平。八十年前,年轻人从这些街道离去,再未归来。他们的牺牲不是为了让我们遗忘,而是为了让我们自由地生活。今天献上的每一朵花,都是铭记他们勇气的承诺。让我们教育孩子:和平珍贵且易失。让我们各尽其力,确保这样的苦难不再发生。', 'uk_female', '[{"q":"Why have the people gathered?","type":"choice","answer":"D","options":["To celebrate a great victory.","To watch a sports match.","To open a new shop.","To honour peace and remember the dead."]},{"q":"What happened to the young men eighty years ago?","type":"choice","answer":"A","options":["They left and never came back.","They became rich traders.","They moved to another town.","They built the peace garden."]},{"q":"What does each flower represent?","type":"choice","answer":"B","options":["A gift for the visitors.","A promise to remember their courage.","A sign of the new season.","A prize for the winners."]},{"q":"What should children be taught?","type":"choice","answer":"C","options":["That war brings glory.","That history does not matter.","That peace is precious and easily lost.","That flowers are expensive."]},{"q":"What does the speaker ask everyone to do?","type":"choice","answer":"D","options":["Forget the past as soon as possible.","Build a stronger army.","Leave the town for good.","Work to prevent such suffering again."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U3', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Short Review of a War Film(写一篇战争电影短评)', 'A Review of a War Film', '请用英语写一篇约100词的战争电影短评。内容包括:① 影片名称、导演及主要人物;② 简述故事或最难忘的一个场景;③ 谈谈影片传达的关于战争与和平的信息;④ 给出你的评价与推荐。注意:特别留意主谓一致(集合名词、and 连接的主语、a number of / the number of)。', 'Write a short review (about 100 words) of a film on the theme of war. Include: 1) the film''s title, director and main characters; 2) a brief account of the story or one unforgettable scene; 3) the message it sends about war and peace; 4) your opinion and recommendation. Pay special attention to subject-verb agreement (collective nouns, subjects joined by ''and'', a number of / the number of).', '["片名+导演+主要人物(… is a war film directed by …)","故事或难忘场景(The film tells the story of … / One scene that stays with me is …)","战争与和平的信息(Its message is simple: … )","评价与推荐(It is an unforgettable film that I would recommend to …)"]'::jsonb, 70, 100, 'Saving Private Ryan is a war film directed by Steven Spielberg. The two main characters are Captain Miller and Private Ryan, the last of four brothers still alive. A small rescue team is sent to bring him home, and the team is led by Miller, a survivor of Omaha Beach. The opening scene, in which the audience is thrown into thirty terrible minutes of the Normandy landings, shows the full horror of war. The number of lives lost is shocking, yet the film is also about courage and sacrifice. Its message is clear: we want peace, not war. I would warmly recommend it.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Saving Private Ryan is a war film directed by Steven Spielberg.","A small rescue team is sent to bring him home, and the team is led by Captain Miller.","The number of lives lost is shocking, yet the film is also about courage and sacrifice.","Its message is clear: we want peace, not war."]'::jsonb, '[{"wrong":"The rescue team are led by Captain Miller.","correct":"The rescue team is led by Captain Miller.","note":"team 在此看作一个整体,谓语用单数 is。"},{"wrong":"The number of lives lost are shocking.","correct":"The number of lives lost is shocking.","note":"the number of 作主语指‘数目’,谓语用单数 is。"},{"wrong":"A number of soldiers was killed on the beach.","correct":"A number of soldiers were killed on the beach.","note":"a number of + 复数名词,谓语用复数 were。"}]'::jsonb, '【战争影评结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U3', '{"title":"主谓一致(1)速查:集合名词 · and 主语 · each/every · a number of / the number of","intro":"主谓一致就是谓语动词的‘数’要和主语的‘数’一致。本单元三大考点:① 集合名词看整体用单数、看成员用复数;② and 连接两者用复数、同一事物用单数;③ each/every/either/neither + 单数,a number of 用复数、the number of 用单数,以及 neither…nor… / either…or… 的就近原则。","table":{"headers":["主语类型","谓语单/复 + 例句"],"rows":[["集合名词作整体","单数:The team is the best in the league.(看作一个队)"],["集合名词指成员","复数:The team are arguing among themselves.(强调队员)"],["A and B(两者)","复数:Tom and Jerry were in the same unit."],["A and B(同一事物)","单数:Bread and butter is on the table. / The poet and soldier is …"],["each/every/either/neither + 名词","单数:Each of the soldiers was given a gun."],["a number of + 复数名词","复数:A number of boats were hit."],["the number of + 复数名词","单数:The number of casualties was rising."],["neither…nor… / either…or…","就近:Neither the captain nor his men were ready."]]},"specialRules":[{"rule":"police / people / cattle 等通常作复数","mark":"The police were searching the area."},{"rule":"every…and every… 与 many a + 单数名词,谓语用单数","mark":"Many a man has died for peace."},{"rule":"集合名词后用 it/itself → 单数;用 they/their/themselves → 复数(靠代词判断)","mark":"The crew did its job. / The crew did their jobs."},{"rule":"a number of(许多)≠ the number of(……的数目),前复后单","mark":"对比 a/the number of"}],"why":["‘数’的一致由主语真正的中心和说话人的视角决定:把集合体当‘一个’还是‘一群’,a number of 强调‘很多个’(复数),the number of 强调‘数目’这一概念(单数);并列主语是否指同一人或同一物,决定用单数还是复数。"],"gaokaoPoints":["语法填空/改错高频:the number of vs a number of 的单复数;集合名词随语境单复数。","neither…nor… / either…or… / not only…but also… 的就近原则。","every…and every… / each + 单数名词、many a + 单数名词一律用单数谓语。"],"examVsReal":[{"exam":"The team is playing well.（看作整体，单数）","real":"英式口语常说 The team are playing well.","note":"英式英语里集合名词常配复数动词;考试按‘整体=单数’更稳。"},{"exam":"Neither of the plans was perfect.（neither of + 单数）","real":"口语里也常听到 Neither of the plans were perfect.","note":"书面/考试用单数 was 最稳妥。"}]}'::jsonb, 'fltrp');
